#include <bits/stdc++.h>
using namespace std;
typedef complex<double> cd;
const double PI = acos(-1);
void fft(vector<cd>& a, bool inv=false){
    int n=a.size();
    for(int i=1,j=0;i<n;i++){int bit=n>>1;for(;j&bit;bit>>=1)j^=bit;j^=bit;if(i<j)swap(a[i],a[j]);}
    for(int len=2;len<=n;len<<=1){
        double ang=2*PI/len*(inv?-1:1);
        cd wlen(cos(ang),sin(ang));
        for(int i=0;i<n;i+=len){cd w(1);for(int j=0;j<len/2;j++,w*=wlen){cd u=a[i+j],v=a[i+j+len/2]*w;a[i+j]=u+v;a[i+j+len/2]=u-v;}}
    }
    if(inv) for(auto&x:a) x/=n;
}
